exec 2>>/run/bsl-sshfs.log 3<&0; u='tester'; uid=$(id -u "$u") || exit 3; gid=$(id -g "$u") || exit 3; h=$(getent passwd "$u" | cut -d: -f6); [ -n "$h" ] && [ -d "$h" ] || exit 3; m="$h"/'Downloads'; mountpoint -q "$m" && umount -l "$m"; [ -d "$m" ] || install -d -o "$uid" -g "$gid" "$m" || exit 3; sshfs -f -o passive,allow_other,default_permissions,uid=$uid,gid=$gid,dcache_timeout=5 breadstick:/ "$m" <&3 & p=$!; trap 'umount -l "$m"; kill $p' HUP TERM; wait $p; st=$?; mountpoint -q "$m" && umount -l "$m"; exit $st
